document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("css-minifier-input"),t=document.getElementById("css-minifier-output"),n=document.getElementById("css-minifier-button"),c=document.getElementById("css-copy-button"),i=document.getElementById("css-clear-button"),o=document.getElementById("css-minifier-message");function s(e,t=!1){o&&(o.textContent=e,o.style.color=t?"#b42318":"#0f8f68")}e&&t&&n&&(n.addEventListener("click",()=>{const n=e.value.trim();if(!n)return t.value="",void s("Please paste some CSS to minify.",!0);const c=function(e){return e.replace(/\/\*[\s\S]*?\*\//g,"").replace(/\s+/g," ").replace(/\s*([{}:;,>+~])\s*/g,"$1").replace(/;}/g,"}").trim()}(n);t.value=c;s(`CSS minified successfully. Saved ${n.length-c.length} characters.`)}),c?.addEventListener("click",async()=>{if(t.value)try{await navigator.clipboard.writeText(t.value),s("Minified CSS copied to clipboard.")}catch(e){t.select(),document.execCommand("copy"),s("Minified CSS copied to clipboard.")}else s("Nothing to copy yet.",!0)}),i?.addEventListener("click",()=>{e.value="",t.value="",s(""),e.focus()}))});